using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

namespace Wizard.Analyzers
{
    // 결정론 금지 목록(ARCHITECTURE 11, T-11, T-42), 공유 패키지의 언어·API 제한(3.3), 계층 참조(3.2), 결제 값 참조(spec 12 10.7),
    // 진단 끄기 금지(T-42), 네임스페이스 = 폴더(CLAUDE.md 6, T-33).
    // 생성 코드(*.g.cs, <auto-generated>)도 검사한다. 파일 이름으로 금지 목록을 피할 수 없다.
    //
    // 대상은 컴파일의 어셈블리 이름으로 정한다(AssemblyRoles):
    //   코어 세 어셈블리(Core, Content, Sim) — 결정론 금지 목록 전부, 모든 억제 금지
    //   공유 패키지(src/ 아홉 + TestKit.Shared) — 언어·API 제한(불안정 정렬 포함), Rules 의 실수형·결제 값, Netcode 의 시계·소켓
    //   서버 프로젝트 — 참조 금지, WZ 진단 억제 금지, 네임스페이스 = 폴더
    // 파일별 처리는 DeterminismAnalyzer.*.cs 에 나눠 두었다.
    [DiagnosticAnalyzer(LanguageNames.CSharp)]
    public sealed partial class DeterminismAnalyzer : DiagnosticAnalyzer
    {
        public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics { get; } = ImmutableArray.Create(Rules.All);

        public override void Initialize(AnalysisContext context)
        {
            context.ConfigureGeneratedCodeAnalysis(GeneratedCodeAnalysisFlags.Analyze | GeneratedCodeAnalysisFlags.ReportDiagnostics);
            context.EnableConcurrentExecution();
            context.RegisterCompilationStartAction(OnCompilationStart);
        }

        private static void OnCompilationStart(CompilationStartAnalysisContext start)
        {
            string? asm = start.Compilation.AssemblyName;
            bool core = AssemblyRoles.IsCore(asm);
            bool shared = AssemblyRoles.IsShared(asm);
            bool server = AssemblyRoles.IsServer(asm);
            if (asm == null || (!core && !shared && !server))
            {
                return;
            }
            var c = new Checker(asm, core, shared);

            // 공유·서버 공통: 참조, 진단 끄기, 네임스페이스 = 폴더
            start.RegisterCompilationEndAction(c.OnCompilationEnd);
            start.RegisterSyntaxTreeAction(c.OnSyntaxTree);
            start.RegisterSyntaxNodeAction(c.OnAttribute, SyntaxKind.Attribute);
            if (!shared)
            {
                return;
            }

            // 이름 참조(금지 타입·멤버)와 실수형
            start.RegisterSyntaxNodeAction(c.OnPredefinedType, SyntaxKind.PredefinedType);
            start.RegisterSyntaxNodeAction(c.OnName, SyntaxKind.IdentifierName, SyntaxKind.GenericName);
            start.RegisterOperationAction(c.OnTypedOperation, OperationKind.Invocation, OperationKind.PropertyReference, OperationKind.FieldReference,
                OperationKind.Conversion, OperationKind.Literal, OperationKind.LocalReference, OperationKind.ParameterReference,
                OperationKind.Binary, OperationKind.ObjectCreation);
            start.RegisterSymbolAction(c.OnMemberSignature, SymbolKind.Method, SymbolKind.Property, SymbolKind.Field, SymbolKind.Event);

            // 언어 제한(ARCHITECTURE 3.3)
            start.RegisterSyntaxNodeAction(c.OnRecord, SyntaxKind.RecordDeclaration, SyntaxKind.RecordStructDeclaration);
            start.RegisterSyntaxNodeAction(c.OnInitAccessor, SyntaxKind.InitAccessorDeclaration);
            start.RegisterSyntaxNodeAction(c.OnFileScopedNamespace, SyntaxKind.FileScopedNamespaceDeclaration);
            start.RegisterSyntaxNodeAction(c.OnUsingDirective, SyntaxKind.UsingDirective);
            start.RegisterSyntaxNodeAction(c.OnListPattern, SyntaxKind.ListPattern);

            // 코어 금지 목록(문법)
            start.RegisterSyntaxNodeAction(c.OnChecked, SyntaxKind.CheckedExpression, SyntaxKind.CheckedStatement);
            start.RegisterSyntaxNodeAction(c.OnUnsafe, SyntaxKind.UnsafeStatement, SyntaxKind.FixedStatement, SyntaxKind.PointerType,
                SyntaxKind.FunctionPointerType);
            start.RegisterSyntaxNodeAction(c.OnLock, SyntaxKind.LockStatement);
            start.RegisterSyntaxNodeAction(c.OnModifiers, SyntaxKind.ClassDeclaration, SyntaxKind.StructDeclaration, SyntaxKind.InterfaceDeclaration,
                SyntaxKind.RecordDeclaration, SyntaxKind.RecordStructDeclaration, SyntaxKind.MethodDeclaration, SyntaxKind.FieldDeclaration,
                SyntaxKind.EventFieldDeclaration, SyntaxKind.EventDeclaration, SyntaxKind.PropertyDeclaration, SyntaxKind.ConstructorDeclaration,
                SyntaxKind.DestructorDeclaration, SyntaxKind.LocalFunctionStatement, SyntaxKind.OperatorDeclaration,
                SyntaxKind.ConversionOperatorDeclaration, SyntaxKind.IndexerDeclaration, SyntaxKind.DelegateDeclaration,
                SyntaxKind.ParenthesizedLambdaExpression, SyntaxKind.SimpleLambdaExpression, SyntaxKind.AnonymousMethodExpression);

            // 코어 금지 목록(의미)
            start.RegisterOperationAction(c.OnInvocation, OperationKind.Invocation);
            start.RegisterOperationAction(c.OnMethodReference, OperationKind.MethodReference);
            start.RegisterOperationAction(c.OnObjectCreation, OperationKind.ObjectCreation);
            start.RegisterSyntaxNodeAction(c.OnGenericName, SyntaxKind.GenericName);
            start.RegisterOperationAction(c.OnBinary, OperationKind.Binary, OperationKind.CompoundAssignment);
            start.RegisterOperationAction(c.OnForEach, OperationKind.Loop);
            start.RegisterOperationAction(c.OnConversion, OperationKind.Conversion);
            start.RegisterOperationAction(c.OnInterpolation, OperationKind.Interpolation);
            start.RegisterOperationAction(c.OnPropertyReference, OperationKind.PropertyReference);
            start.RegisterOperationAction(c.OnOutsideCoreHashOperation, OperationKind.PropertyReference, OperationKind.Binary, OperationKind.Unary,
                OperationKind.CompoundAssignment, OperationKind.Conversion, OperationKind.Increment, OperationKind.Decrement);
            start.RegisterSymbolAction(c.OnField, SymbolKind.Field);
            start.RegisterSymbolAction(c.OnProperty, SymbolKind.Property);
            start.RegisterSymbolAction(c.OnEvent, SymbolKind.Event);
        }

        private sealed partial class Checker
        {
            private readonly string _asm;
            private readonly bool _core;
            private readonly bool _shared;
            private readonly bool _floatBanned;
            private readonly bool _clockBanned;

            public Checker(string asm, bool core, bool shared)
            {
                _asm = asm;
                _core = core;
                _shared = shared;
                _floatBanned = AssemblyRoles.BansFloatingPoint(asm);
                _clockBanned = AssemblyRoles.BansClock(asm);
            }

            public void OnCompilationEnd(CompilationAnalysisContext ctx)
            {
                CheckReferences(ctx);
                CheckSuppressingOptions(ctx);
                CheckOneNamespacePerFolder(ctx);
                if (_shared)
                {
                    CheckLanguageVersion(ctx);
                }
                if (_core)
                {
                    CheckCoreCompilationOptions(ctx);
                }
            }

            public void OnSyntaxTree(SyntaxTreeAnalysisContext ctx)
            {
                CheckPragmas(ctx);
                CheckNamespaceFolder(ctx);
                if (_shared)
                {
                    CheckNewerLiterals(ctx);
                }
            }

            // ---------- 참조(WZ0023) ----------
            private void CheckReferences(CompilationAnalysisContext ctx)
            {
                foreach (AssemblyIdentity id in ctx.Compilation.ReferencedAssemblyNames)
                {
                    if (AssemblyRoles.IsForbiddenReference(_asm, id.Name))
                    {
                        ctx.ReportDiagnostic(Diagnostic.Create(Rules.LayerReference, Location.None, _asm, id.Name));
                    }
                }
            }

            // ---------- 코어의 컴파일 옵션: AllowUnsafeBlocks(WZ0012), CheckForOverflowUnderflow(WZ0015) ----------
            private void CheckCoreCompilationOptions(CompilationAnalysisContext ctx)
            {
                if (ctx.Compilation.Options is CSharpCompilationOptions cs && cs.AllowUnsafe)
                {
                    ctx.ReportDiagnostic(Diagnostic.Create(Rules.UnsafeCode, Location.None, _asm));
                }
                if (ctx.Compilation.Options.CheckOverflow)
                {
                    ctx.ReportDiagnostic(Diagnostic.Create(Rules.CheckedContext, Location.None, _asm));
                }
            }
        }
    }
}
